// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    // allow the contract to pay out its withdrawn Ether to us (the owner)
    receive() external payable {}

    function setUp() public {
        c = new SimpleWallet();
    }

    function testFuzz_property(uint256 amount) public {
        // admissible domain: a fundable, transferable positive balance
        amount = bound(amount, 1, 1e30);

        // fund the contract directly (owner is the deployer, i.e. this test contract)
        vm.deal(address(c), amount);

        // owner calls withdrawAll; payout goes to msg.sender (this contract), which accepts ETH
        vm.prank(address(this));
        c.withdrawAll();

        assertTrue(address(c).balance == 0);
    }
}
